/* GNU ld version script for the public LibreSCRS_*.so libraries.
 * Exports the entities of the LibreSCRS namespace; everything else (bundled
 * OpenSSL, libresign internals, vendored nlohmann/miniz/pugixml, and every
 * standard-library template instantiation, including one instantiated on a
 * LibreSCRS type) collapses to local linkage.
 * See lib/LibreSCRS/CMakeLists.txt for full rationale.
 *
 * Syntax: the global patterns are plain (C-language) globs, so they match
 * the MANGLED name. Each one is anchored on a nested name rooted in
 * `9LibreSCRS`, after the Itanium-ABI prefix of its kind:
 *     _ZN / _ZNK / _ZNV / _ZNVK / _ZNR / _ZNO / _ZNKR / _ZNKO
 *                               functions and data, with their cv- and
 *                               ref-qualifiers
 *     _ZTV / _ZTI / _ZTS / _ZTT / _ZTC
 *                               vtable, typeinfo, typeinfo name, VTT,
 *                               construction vtable -- required for
 *                               cross-SO polymorphism (dynamic_cast,
 *                               exception catch, vtable lookup of public
 *                               abstract bases such as `ISecureChannel`)
 *     _ZGV / _ZZ / _ZTH / _ZTW  guard variables and local statics of
 *                               inline functions (one copy per process),
 *                               thread_local init and wrapper
 *     _ZThn / _ZTv              non-virtual and virtual thunks
 * The demangled form cannot be anchored the same way: GNU ld refuses spaces
 * in an unquoted `extern "C++"` pattern and treats a quoted one as a
 * literal, so `typeinfo for LibreSCRS::Foo` forces a leading-wildcard
 * `*LibreSCRS::*` glob -- and that glob also matched every symbol whose
 * demangled name merely MENTIONS a LibreSCRS type, such as
 * `std::__detail::_Map_base<..., LibreSCRS::<an enum>>::operator[]`
 * or `vtable for std::_Sp_counted_ptr_inplace<LibreSCRS::Trust::TrustStore,
 * ...>`. Exported weak, those bind every consumer instantiating the same
 * template to whichever copy loaded first.
 * ci/scripts/check-impl-visibility.sh refuses any such export.
 *
 * Cross-`.so` ABI surface — INTENTIONAL Internal::/detail:: exports:
 *   The LibreSCRS::*::Internal:: namespace IS part of the SHARED-build
 *   ABI for cross-`.so` plugin reach and the test-helper archive.
 *   Specifically:
 *     - LibreSCRS::SmartCard::Internal::PCSCConnection,
 *       ActiveChannelAccessor — reached across the .so boundary by the
 *       card plugins and the test-helper archive.
 *       Monitor, the APDU helpers and the plugin PIN-family quirks are
 *       compiled into each image from hidden-visibility archives and
 *       are not exported.
 *     - LibreSCRS::SecureChannel::detail::ChannelStateMutator —
 *       required for SmartCard.so + emrtd-plugin.so to call
 *       SetCurrentApplet / ReplaceKeys.
 *     - LibreSCRS::SmartCard::Internal::HolderChannelAccessor —
 *       required for plugin .so files to obtain a channel pointer
 *       from a holder.
 *     - LibreSCRS::Trust::detail::TrustStoreInternalAccess::
 *       mergeTrustedListAnchors — required for Signing.so to merge
 *       anchors into Trust.so's store.
 *     - LibreSCRS::Trust::detail::TrustAnchorProvider typeinfo —
 *       required for cross-`.so` dynamic_cast on subclasses linked in
 *       different .so files.
 *   Third-party consumers MUST NOT rely on Internal:: or detail::
 *   symbols; both are unstable across minor releases and are exported
 *   only because the shared-build link graph mechanically requires
 *   it.
 *
 *   SM-aware transmit funnel: the only exported entry point is
 *   `CardSession::transmitInternal()` (internal-build-gated public
 *   member), exported by the `_ZN9LibreSCRS*` family.
 *   The snapshot/dispatch primitive is a TU-local anonymous-namespace
 *   helper inside `CardSession.cpp` and is not exported; the legacy
 *   `LibreSCRS::SmartCard::Internal::sessionTransmitImpl` free
 *   function, the `detail::sessionTransmit` overload, and the
 *   `CardSession::impl{Mutex,ActiveChannelSnapshot,OwnedConn}`
 *   accessors are intentionally absent from the dynamic export set.
 */

LM_5 {
    global:
        /* The prefix families of the file header, each anchored on
         * `9LibreSCRS` right after it. A `*` never comes before the
         * anchor except inside a thunk's offset. */
        _ZN9LibreSCRS*;
        _ZNK9LibreSCRS*;
        _ZNV9LibreSCRS*;
        _ZNVK9LibreSCRS*;
        _ZNR9LibreSCRS*;
        _ZNO9LibreSCRS*;
        _ZNKR9LibreSCRS*;
        _ZNKO9LibreSCRS*;
        _ZTVN9LibreSCRS*;
        _ZTIN9LibreSCRS*;
        _ZTSN9LibreSCRS*;
        _ZTTN9LibreSCRS*;
        _ZTCN9LibreSCRS*;
        _ZGVN9LibreSCRS*;
        _ZGVZN9LibreSCRS*;
        _ZGVZNK9LibreSCRS*;
        _ZZN9LibreSCRS*;
        _ZZNK9LibreSCRS*;
        _ZTHN9LibreSCRS*;
        _ZTWN9LibreSCRS*;
        _ZThn*_N9LibreSCRS*;
        _ZThn*_NK9LibreSCRS*;
        _ZTv*_N9LibreSCRS*;
        _ZTv*_NK9LibreSCRS*;
    local:
        /* Everything else. A local pattern cannot carve an exception out
         * of a global wildcard -- GNU ld lets the global wildcard win and
         * only a literal local name overrides it -- so a LibreSCRS entity
         * that must not be exported stays out of these libraries instead:
         * the test seams are compiled into the test archives
         * (`LibreSCRS_SmartCard_TestHelpers`, `LibreSCRS_SmartCardTesting`),
         * never into a .so. */
        *;
};
